-- =============================================================================
-- 0032_curriculum_topics.sql · 国家课标自建多科目知识点维度表
-- =============================================================================
-- 提案：docs/design/method/proposals/P-027-国家课标自建多科目知识点维度表实施.md
-- 台账：decision-log.md D-038 / D-039
-- 日期：2026-11-12
--
-- 🔴 唯一取数源＝教育部官方文本：
--    教材〔2022〕2号《义务教育课程方案和课程标准（2022年版）》16 门课标
--    教材〔2025〕1号《中小学课程方案和课程标准日常修订版》通知与附件
--    ⛔ 未使用、未复制 cn-math-taxonomy（CC BY-NC 4.0）任何数据、编号或表达。
--    该仓库 cn-curriculum-standards.json 803 条中 verbatim=false 646 / 空 157 / 逐字 0，
--    是作者转述而非课标原文，改名导入绕不开许可（D-038 §3）。

--    数学  : 数与代数/图形与几何/统计与概率/综合与实践（2022 版四领域）
--    语文  : 6 个学习任务群（教育部 2022-04-21 发布会 / moe.gov.cn 转载）
--    物理  : 物质/运动和相互作用/能量/实验探究/跨学科实践（教育部官网 PDF W020220420582357585169.pdf）
--    化学  : 5 个学习主题（科学探究与化学实验、物质的性质与应用、物质的组成与结构、
--           物质的化学变化、化学与社会·跨学科实践；人民日报/教育平台转载 16 科解读）
--    生物学: 7 个学习主题（教育部官网 PDF W020220420582359998122.pdf）
--    历史  : 7 个板块（教育部官网 PDF W020220420582345700037.pdf 目录）
--    地理  : 认识全球/认识区域/地理工具/地理实践/跨学科主题学习
--           （教育部官网 PDF W020220420582354066450.pdf 图 2 地理课程内容结构）
--    道法  : 「成长中的我」为原点 + 5 个核心素养（教育部 2022-04-21 发布会）
--    ⚠️ 英语义教段一级要素、以及全部高中段领域，未逐科核对官方文本
--       ⇒ framework_verified=false，见 version_note。
--    ⚠️ 各科仅选用官方框架中的部分一级主题，不宣称覆盖课标全部内容。
--
-- 🔴 数据分层（不得混同）：
--    domain / topic = 官方课标公开可核验的一级框架名 / 二级主题
--        → framework_verified=true（仅上列已核验学科、仅义教段）
--    term = 本项目为检索自建的通用学科术语，不是课标条文、不是知识点官方定义
--        → term_origin='project'（全表恒定）
--    未逐科核对官方文本的行 → framework_verified=false，见 version_note
--
-- 🔴 范围（D-039）：仅项目库 DEFAULT_SUBJECTS 中有对应国家课标的 9 门学科；
--    「生活」无对应国标课标 ⇒ 不引入；科学 / 信息科技 / 体育与健康 / 艺术 /
--    劳动 / 日语 / 俄语等文件中的其他科目与本项目无关 ⇒ 不引入。
--
-- 🔴 与 question_objects（656,898 行）完全解耦：独立维度表，无外键、无回填、
--    不牵动判定层契约 sha / CACHE_VERSION v14 / 第二层准入。
--    全局只读字典（不是用户数据，故无 user_id）；服务端只允许 SELECT，不暴露写端点。
--
-- 幂等：if not exists + on conflict do nothing
-- =============================================================================

create table if not exists curriculum_topics (
  id                  bigserial primary key,
  subject_code        text        not null,
  subject_name        text        not null,
  standard_name       text        not null,
  stage               text        not null check (stage in ('小学', '初中', '高中')),
  grade_min           smallint    not null check (grade_min between 1 and 12),
  grade_max           smallint    not null check (grade_max between 1 and 12),
  domain              text        not null,
  topic               text        not null,
  term                text        not null,
  standard_version    text        not null,
  standard_doc        text        not null,
  source_url          text        not null default '',
  framework_verified  boolean     not null default false,
  term_origin         text        not null default 'project' check (term_origin in ('project')),
  version_note        text        not null default '',
  created_at          timestamptz not null default now(),
  constraint curriculum_topics_uq unique (subject_code, stage, domain, topic, term),
  constraint curriculum_topics_grade_chk check (grade_min <= grade_max),
  constraint curriculum_topics_subject_chk check (
    subject_code in ('chinese','math','english','physics','chemistry','biology','history','geography','politics')
  )
);

create index if not exists curriculum_topics_subject_stage_idx on curriculum_topics (subject_code, stage);
create index if not exists curriculum_topics_term_idx on curriculum_topics (term);

comment on table curriculum_topics is
  '国家课标自建多科目知识点维度表（P-027 / D-039）。domain/topic 为官方课标框架名，term 为本项目自建检索术语；与 question_objects 解耦，只读字典。';

